"""Small login function used by the coding-agent demo."""

from config import DEMO_PASSWORD, DEMO_USERNAME


def login(username: str, password: str) -> bool:
    """Accept only the exact example credentials; empty input is rejected."""
    if not username or not password:
        return False
    return _credentials_match(username, password)


def _credentials_match(username: str, password: str) -> bool:
    """Compare demo credentials without changing authentication behavior."""
    return username == DEMO_USERNAME and password == DEMO_PASSWORD

import pytest
from login import _credentials_match

@pytest.mark.parametrize("username,password,expected", [
    ("demo", "demo-only", True), ("unknown", "demo-only", False),
    ("demo", "wrong", False), ("", "demo-only", False),
    ("Demo", "demo-only", False),
])
def test_credential_comparison(username, password, expected):
    assert _credentials_match(username, password) is expected
